SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.status, pd.create_user_id, pd.create_time, pi.spec_type, ps.is_marketable, pd.process_id, pi.property, pi.name_en, pi.brand_name, pi.grade, pd.charge_name AS productChargeName, pd.first_mass_product_date, pd.plan_listing_time, pp.trial_production_qty, pp.ean, pp.delivery_cycle, pp.main_supplier, ps.year_sale_qty, ps.year_sale_amount, ps.listing_time, ps.delisting_time, pi.sales_channel, pi.category, pi.sale_method, ps.sale_state, ppk.box_qty, pp.moq, pl.declare_model, pl.declare_chinese_name, pd.variant_property FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT join product_sale ps on pd.id = ps.sku_id AND ps.is_deleted = FALSE left join product_pack ppk on pd.id = ppk.sku_id AND ppk.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id and pl.is_deleted = FALSE WHERE pi.delete_state = 0 AND pi.is_deleted = FALSE
AND (pi.spu_no LIKE concat('%',#{params.no},'%') OR pd.sku_no LIKE concat('%',#{params.no},'%') OR pd.name LIKE concat('%', #{params.no},'%'))
AND pd.product_id = #{params.productId}
AND pd.name LIKE concat('%', #{params.name},'%')
AND pd.is_change = #{params.isChange}
AND pd.status in
#{item}
AND pd.product_state in
#{state}
AND pi.category_id in
#{category}
AND pi.grade_id IN
#{gradeId}
AND ps.sale_state IN
#{saleState}
AND pi.brand_id IN
#{brandId}
AND pi.property_id IN
#{propertyId}
AND pi.project_charge_id IN
#{projectChargeId}
AND
string_to_array(#{chargeId},',') && string_to_array(pi.charge_id,',')
AND pd.charge_id in
#{chargeId}
AND pd.process_id in
#{processId}
AND pi.name LIKE concat('%',#{params.productName},'%')
AND pd.status IN
#{status}
AND pi.pirate_risk IN
#{pirateRisk}
AND pi.sale_method IN
#{saleMethod}
AND pd.sku_no IN
#{item}
AND pi.spu_no IN
#{item}
AND pp.main_supplier IN
#{item}
AND pp.ean LIKE concat('%',#{params.ean},'%')
AND pd.create_time >=#{params.startTime}
AND pd.create_time <= #{params.endTime}
${params.param}
ORDER BY pd.create_time DESC

SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.create_user_id, pd.create_time, pi.spec_type, pd.status FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE WHERE pi.delete_state = 0 AND pi.is_deleted = FALSE
AND pi."name" = #{name}
AND pd.sku_no = #{skuNo}
LIMIT 1

SELECT pd.sku_no as skuNo, pi.category, pi.sale_method as saleMethod, pi.sell_spot as sellSpot, pi.function_desc as functionDesc, pi.usage_desc as usageDesc, CASE WHEN pi.pirate_risk = 1 THEN '是' ELSE '否' END pirate_risk, pi.materials, pd.name, pi.brand_name as brandName, pi.property, to_char(pd.plan_listing_time, 'YYYY/MM/dd') as planListingTimeStr, unit.name as unitName, pd.charge_name as chargeName, target_tax_cost as targetTaxCost, target_no_tax_cost as targetNoTaxCost, actual_tax_cost as actualTaxCost, actual_no_tax_cost as actualNoTaxCost, retail_price as retailPrice, target_gpm as targetGpm, actual_gpm_cny as actualGpmCny, actual_gpm_usd as actualGpmUsd, year_sale_qty as yearSaleQtyStr, year_sale_amount as yearSaleAmountStr, month_sale_qty as monthSaleQtyStr, month_sale_amount as monthSaleAmountStr, ps.sale_country as saleCountry, to_char(listing_time, 'YYYY/MM/dd') as listingTimeStr, to_char(delisting_time, 'YYYY/MM/dd') as delistingTimeStr, CASE WHEN is_finished_img = 1 THEN '是' ELSE '否' END isFinishedImg, CASE WHEN is_finished_video = 1 THEN '是' ELSE '否' END isFinishedVideo, sale_state as saleState, dp.value AS productProperty, declare_chinese_name as declareChineseName, declare_english_name as declareEnglishName, declare_price as declarePriceStr, customs_code as customsCode, declare_element as declareElement, english_material as englishMaterial, english_usage as englishUsage, split_part(product_size, 'X',1) as productSizeLengthStr, split_part(product_size, 'X',2) as productSizeWideStr, split_part(product_size, 'X',3) as productSizeHighStr, gross_weight as grossWeightStr, net_weight as netWeightStr, split_part(box_size, 'X',1) as boxSizeLengthStr, split_part(box_size, 'X',2) as boxSizeWideStr, split_part(box_size, 'X',3) as boxSizeHighStr, box_weight as boxWeightStr, box_qty as boxQtyStr, pp.ean, pp.plan_order_qty as planOrderQtyStr, to_char(pp.place_order_time, 'YYYY/MM/dd') as placeOrderTimeStr, to_char(pp.plan_arrival_time, 'YYYY/MM/dd') as planArrivalTimeStr, pp.moq as moqStr, pp.delivery_cycle as deliveryCycleStr, to_char(pp.actual_arrival_time, 'YYYY/MM/dd') as actualArrivalTimeStr, pp.actual_arrival_qty as actualArrivalQtyStr, pp.arrival_state as arrivalState, pp.purchase_user_id AS purchaseUser, pp.main_supplier as mainSupplier, pp.second_supplier as secondSupplier, pd.product_state as productStateName, to_char(pd.first_mass_product_date, 'YYYY/MM/dd') as firstMassProductDateStr FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id AND pd.is_deleted = FALSE LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" AND pp.is_deleted = FALSE LEFT JOIN product_cost pc ON pc.sku_id = pd."id" AND pc.is_deleted = FALSE LEFT JOIN product_sale ps ON ps.sku_id = pd."id" AND ps.is_deleted = FALSE LEFT JOIN product_pack ppk ON ppk.sku_id = pd."id" AND ppk.is_deleted = FALSE LEFT JOIN product_logistics pl ON pl.sku_id = pd."id" AND pl.is_deleted = FALSE LEFT JOIN product_unit unit ON pd.unit_id = unit.id AND unit.is_deleted = FALSE LEFT JOIN basic_dict dp ON pl.product_property_id = dp.id AND dp.is_deleted = FALSE WHERE pi.delete_state = 0 AND pi.is_deleted = FALSE
AND (pi.spu_no LIKE concat('%',#{params.no},'%') OR pd.sku_no LIKE concat('%',#{params.no},'%'))
AND pd.product_state in
#{state}
AND pd.id in
#{skuId}

