SELECT pi.spu_no, pi.name AS spuName, pd.sku_no, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE pi.delete_state = 0 AND pd.is_deleted = FALSE
AND pd.sku_no IN
#{sku}

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property, pp.box_qty as unitQty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_pack pp on pd.id = pp.sku_id AND pp.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE WHERE pi.delete_state = 0 AND pd.is_deleted = FALSE
AND pd.status=#{state}
AND ( pd.sku_no LIKE concat('%',#{searchKeyword},'%') OR pd.name LIKE concat('%',#{searchKeyword},'%') )

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE pi.delete_state = 0 AND pd.is_deleted = FALSE
AND pd.id IN
#{skuId}

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE WHERE pi.delete_state = 0 AND pd.status = #{state} AND pd.is_deleted = FALSE and pd.id not in ( select DISTINCT parent_sku_id from product_bom_sku
bom_id != #{bomId}
)
AND ( pd.sku_no LIKE concat('%',#{searchKeyword},'%') OR pd.name LIKE concat('%',#{searchKeyword},'%') )

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.images_url AS skuImagesUrl, pd.name AS skuName, pd.variant_property as variantProperty, pl.declare_chinese_name as declareName, pl.declare_model as declareModel, pl.product_property_id AS productPropertyId, pi.materials, pi.function_desc, pi.grade AS productGrade, pi.brand_name as brandName, ps.sale_state as saleState, pd.unit_name FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id AND pi.is_deleted = FALSE left join product_logistics pl on pd.id = pl.sku_id AND pl.is_deleted = FALSE left join product_sale ps on pd.id = ps.sku_id and ps.is_deleted = FALSE WHERE pi.delete_state = 0 AND pd.is_deleted = FALSE
AND pd.id IN
#{skuId}
